function cuteArt(n){const hue=(n*47+245)%360;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 300"><defs><radialGradient id="bg"><stop stop-color="hsl(${hue} 30% 25%)"/><stop offset="1" stop-color="#101326"/></radialGradient><linearGradient id="main" x1="0" y1="0" x2="1" y2="1"><stop stop-color="hsl(${hue} 85% 85%)"/><stop offset=".45" stop-color="hsl(${hue} 63% 66%)"/><stop offset="1" stop-color="hsl(${(hue+35)%360} 48% 40%)"/></linearGradient><linearGradient id="petal" x2=".8" y2="1"><stop stop-color="#f9dfaa"/><stop offset=".4" stop-color="#b6b9f0"/><stop offset="1" stop-color="#7d5cb8"/></linearGradient><linearGradient id="mint" x2="1" y2="1"><stop stop-color="#d9f4cb"/><stop offset=".4" stop-color="#82d7d3"/><stop offset="1" stop-color="#377f9e"/></linearGradient><linearGradient id="gold" x2=".7" y2="1"><stop stop-color="#fff0c3"/><stop offset=".45" stop-color="#f5c192"/><stop offset="1" stop-color="#c17b90"/></linearGradient><linearGradient id="skin" x2="1" y2="1"><stop stop-color="#ffe6b9"/><stop offset="1" stop-color="#d89494"/></linearGradient><linearGradient id="hair" x2="1" y2="1"><stop stop-color="#74506e"/><stop offset="1" stop-color="#39283f"/></linearGradient><linearGradient id="mirror" x2="1" y2="1"><stop stop-color="#d3dfff"/><stop offset=".45" stop-color="#aa96d7"/><stop offset="1" stop-color="#735f9c"/></linearGradient><linearGradient id="shade" x2="0" y2="1"><stop stop-color="#603e75"/><stop offset="1" stop-color="#2d2042"/></linearGradient><filter id="shadow" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="0" dy="8" stdDeviation="7" flood-color="#09050c" flood-opacity=".5"/></filter><filter id="grain"><feTurbulence baseFrequency=".7" numOctaves="2" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".045"/></feComponentTransfer><feBlend in="SourceGraphic" mode="soft-light"/></filter><radialGradient id="halo"><stop stop-color="hsl(${hue} 80% 75%)" stop-opacity=".2"/><stop offset="1" stop-color="hsl(${hue} 80% 75%)" stop-opacity="0"/></radialGradient></defs><rect width="300" height="300" fill="url(#bg)"/><ellipse cx="150" cy="150" rx="130" ry="130" fill="url(#halo)"/><ellipse cx="150" cy="250" rx="91" ry="11" fill="none" stroke="#f7b9d0" stroke-opacity=".25"/><ellipse cx="150" cy="250" rx="65" ry="6" fill="#ed9ac0" opacity=".12"/><g filter="url(#shadow)">${shapes[n]()}</g><g fill="#ffe6c5" opacity=".6"><circle cx="57" cy="80" r="1.4"/><circle cx="247" cy="140" r="1.3"/><circle cx="80" cy="45" r="1"/><circle cx="225" cy="50" r="1.4"/></g></svg>`;}

